question.solution:
def tlb_eat(hit_rate, tlb_time, mem_time):
    return tlb_time + mem_time + (1 - hit_rate) * mem_time

def tlb_needed_rate(target_eat, tlb_time, mem_time):
    if target_eat <= tlb_time + mem_time:
        return 1.0
    if target_eat >= tlb_time + 2 * mem_time:
        return 0.0
    return 1 - (target_eat - tlb_time - mem_time) / mem_time

print(tlb_eat(0.9, 20, 100))
print(tlb_needed_rate(125, 20, 100))
print(tlb_eat(1.0, 20, 100))
print(tlb_eat(0.0, 20, 100))
